def copy_reading_records(apps, schema_editor):
    """Les guides déjà lus deviennent des éléments « lus » de Ma lecture."""
    ReadingRecord = apps.get_model("catalogue", "ReadingRecord")
    ReadingListItem = apps.get_model("catalogue", "ReadingListItem")
    for position, record in enumerate(ReadingRecord.objects.order_by("read_at"), start=1):
        ReadingListItem.objects.get_or_create(
            user_id=record.user_id, guide_id=record.guide_id,
            defaults={"position": position, "added_at": record.read_at,
                      "started_at": record.read_at, "finished_at": record.read_at})


